/**
 * How each place appears across the map snapshots: the years that draw it,
 * its size in each, its neighbours at its largest, and what the map shows in
 * the same spot just before and after. This is the site's own data, so it
 * gives every /place page something no encyclopedia has.
 *
 * placeMaps.json is generated by scripts/build-place-maps.mts (it reads all
 * the snapshots, too slow per request). Re-run it after editing the crosswalk.
 */
import PLACE_MAPS from "@/data/placeMaps.json";
import { SNAPSHOT_YEARS } from "@/data/snapshotYears";

export interface MapLabel {
  name: string;
  slug?: string;
}

export interface PlaceMaps {
  name: string;
  /** Snapshot years that draw this place, oldest first. */
  years: number[];
  /** [year, km²] for each of those years. */
  area: [number, number][];
  /** Largest extent, and the snapshot names counted in it. */
  peak: { year: number; km2: number; parts: string[] };
  /** Neighbours at the peak that have their own atlas page. */
  neighbours: MapLabel[];
  /** What the snapshot before the first appearance shows in the same spot. */
  before: (MapLabel & { year: number }) | null;
  /** What the snapshot after the last appearance shows in the same spot. */
  after: (MapLabel & { year: number }) | null;
  /** Modern countries covering its largest extent, with their share of it (0–1). */
  today?: { name: string; share: number }[];
}

/** The 2010 snapshot's older country names, as people search for them now. */
const MODERN_NAMES: Record<string, string> = {
  Burma: "Myanmar",
  Byelarus: "Belarus",
  Zaire: "the Democratic Republic of the Congo",
  Congo: "the Republic of the Congo",
  Swaziland: "Eswatini",
  "Korea, Democratic People's Republic of": "North Korea",
  "Korea, Republic of": "South Korea",
  "Tanzania, United Republic of": "Tanzania",
  "United Kingdom": "the United Kingdom",
  "United States": "the United States",
  "Czech Republic": "the Czech Republic",
  "Central African Republic": "the Central African Republic",
  Netherlands: "the Netherlands",
};
export const modernName = (name: string) => MODERN_NAMES[name] ?? name;

export function placeMaps(slug: string): PlaceMaps | undefined {
  return (PLACE_MAPS as unknown as Record<string, PlaceMaps>)[slug];
}

/** Snapshots from 10,000 BCE on — the ones a visitor can actually open. */
export const MAP_COUNT = SNAPSHOT_YEARS.filter((y) => y >= -10000).length;

/** True when the place is drawn on every snapshot between its first and last. */
export function drawnContinuously(years: number[]): boolean {
  const from = SNAPSHOT_YEARS.indexOf(years[0]);
  const to = SNAPSHOT_YEARS.indexOf(years[years.length - 1]);
  return from !== -1 && to !== -1 && to - from + 1 === years.length;
}

/** Modern countries for "roughly the size of …" (km², rounded). */
const YARDSTICKS: [string, number][] = [
  ["Luxembourg", 2_590],
  ["Cyprus", 9_250],
  ["Belgium", 30_700],
  ["Switzerland", 41_300],
  ["Ireland", 70_300],
  ["Portugal", 92_200],
  ["Greece", 132_000],
  ["the United Kingdom", 243_600],
  ["Italy", 302_000],
  ["Germany", 357_600],
  ["Spain", 506_000],
  ["France", 551_700],
  ["Turkey", 783_600],
  ["Egypt", 1_002_000],
  ["Iran", 1_648_000],
  ["Mexico", 1_964_000],
  ["India", 3_287_000],
  ["Australia", 7_692_000],
  ["the United States", 9_834_000],
  ["Russia", 17_098_000],
];

/** The modern country closest in size (by ratio), or null when nothing is close. */
export function sizeComparison(km2: number): string | null {
  let best: [string, number] | null = null;
  for (const [name, size] of YARDSTICKS) {
    const ratio = Math.max(km2, size) / Math.min(km2, size);
    if (!best || ratio < best[1]) best = [name, ratio];
  }
  return best && best[1] <= 1.35 ? best[0] : null;
}

/** "1,234,000 km² (476,000 sq mi)", rounded to three significant figures. */
export function formatArea(km2: number): string {
  const round = (n: number) => {
    if (n < 1000) return Math.round(n);
    const p = 10 ** (Math.floor(Math.log10(n)) - 2);
    return Math.round(n / p) * p;
  };
  return `${round(km2).toLocaleString("en-US")} km² (${round(km2 / 2.58999).toLocaleString("en-US")} sq mi)`;
}

const TITLED = /\b(Empire|Caliphate|Khanate|Khaganate|Sultanate|Republic|Kingdom|Dynasty|Shogunate|Confederacy|Confederation|Commonwealth|Union|Horde|Emirates?|League|Federation|Raj|Protectorate|Mandate|Territory|Order|Netherlands|Philippines|Bahamas)$/i;
const OF_TITLE = /^(Kingdom|Empire|Emirate|Republic|Duchy|Grand Duchy|Crown|Sultanate|Caliphate|County|Principality|Electorate|State|Khanate|Despotate|Margraviate|Viceroyalty|Captaincy|Dominion|Free State|Union) of\b/;
const ACRONYM_THE = /^(USSR|UK|USA|UAE)$/;

/**
 * "the Mongol Empire", "the Mongols", but "France" and "Tibet": whether a map
 * name reads naturally with "the" in running text.
 */
export function withArticle(name: string): string {
  if (/^the\s/i.test(name)) return name;
  const plural = /[a-z]s$/.test(name) && !/(us|ss|is|os)$/.test(name);
  return TITLED.test(name) || OF_TITLE.test(name) || ACRONYM_THE.test(name) || plural || /^United\s/.test(name)
    ? `the ${name}`
    : name;
}

/**
 * A place page's search-result description from the atlas's own measurements,
 * e.g. "Map of the Pala Empire, 700–1100 CE: at its largest, in 900 CE, about
 * 447,000 km² in today's India and Bangladesh, roughly the size of Spain.
 * Borders, neighbours and history." `dates` are its own (from Wikidata) when
 * known; otherwise the span of the maps is used. Undefined when the snapshots
 * never draw it.
 */
export function placeDescription(slug: string, name: string, dates?: string): string | undefined {
  const data = placeMaps(slug);
  if (!data?.years.length) return undefined;
  const fmt = (y: number) => (y < 0 ? `${-y} BCE` : `${y} CE`);
  const { years, peak } = data;
  const [first, last] = [years[0], years[years.length - 1]];
  // Its own dates when known ("1526–1857"); otherwise the span of the maps that draw it.
  const span = dates ? dates : first === last ? fmt(first) : first < 0 && last < 0 ? `${-first}–${-last} BCE` : first < 0 ? `${fmt(first)}–${fmt(last)}` : `${first}–${last} CE`;
  const area = formatArea(peak.km2).split(" (")[0];
  const like = sizeComparison(peak.km2);
  const today = (data.today ?? []).filter((t, i) => i < 2 || t.share >= 0.1).slice(0, 3).map((t) => modernName(t.name));
  const where = today.length ? ` in today's ${today.length > 1 ? `${today.slice(0, -1).join(", ")} and ${today[today.length - 1]}` : today[0]}` : "";
  const when = years.length > 1 ? `at its largest, in ${fmt(peak.year)}, ` : "";
  // Longest version that fits what Google shows (about 158 characters).
  const versions = [
    `Map of ${withArticle(name)}, ${span}: ${when}about ${area}${where}${like ? `, roughly the size of ${like}` : ""}. Borders, neighbours and history.`,
    `Map of ${withArticle(name)}, ${span}: ${when}about ${area}${where}. Borders, neighbours and history.`,
    `Map of ${withArticle(name)}, ${span}: ${when}about ${area}${where}.`,
    `Map of ${withArticle(name)}, ${span}: about ${area}${where}.`,
  ];
  return versions.find((v) => v.length <= 158) ?? versions[versions.length - 1];
}
